const { irissdk } = require('./import_irissdk.js')
const IRISReference = irissdk.IRISReference

/**
 * Helper class that is used during iteration. Objects of this class act like markers for
 * the start and the end of the iteration as well as moving cursors.
 */
 class _point {

  /**
   * Constructs a new _point
   * @param {*} key a subscript or undefined if the point is a marker
   * @param {*} inclusive whether the subscript should be included or not in the iteration output
   */
  constructor (key, inclusive = undefined) {
    this._key = key
    this._inclusive = inclusive
    this._beforeFirst = false
    this._afterLast = false
  }

  /**
   * Returns whether the current _point marks the start of the subscript list
   * @returns true if the current _point marks the start of the subscript list, false otherwise
   */
  marksFirst () {
    return this._beforeFirst
  }

  /**
   * Returns whether the current _point marks the end of the subscript list
   * @returns true if the current _point marks the end of the subscript list, false otherwise
   */
  marksLast () {
    return this._afterLast
  }

  /**
   * Returns a new _point that marks the start of the subscript list
   * @returns a new marker _point
   */
  static BEFOREFIRST() {
    const firstMarker = new _point(undefined, false)
    firstMarker._beforeFirst = true
    return firstMarker
  }

  /**
   * Returns a new _point that marks the end of the subscript list
   * @returns a new marker _point
   */
  static AFTERLAST() {
    const lastMarker = new _point(undefined, false)
    lastMarker._afterLast = true
    return lastMarker
  }

  
  /**
   * Returns the sorted order of two points.
   * @param {Iris} irisnative the iris instance to use to communicate with the IRIS server
   * @param {string} globalName the name of the global node whose subscripts we want to sort
   * @param {_point} X a point to sort
   * @param {_point} Y a point to sort 
   * @returns 0 if equal, -1 if X if first and 1 if Y is first
   */
   static _sortOrder (irisnative, globalName, X, Y) {
    
    if ((X.marksFirst() && Y.marksFirst()) 
     || (X.marksLast() && Y.marksLast())) {
      return 0
    }
    // TODO: When Y or X is a marker then _key is undefined.
    // Can this create problems? For example in the first if Y might be a last marker...

    if (X.marksFirst()) {
      const referenceY = new IRISReference(Y._key, IRISReference.Type.STRING)
      irisnative._sortOrder(globalName, referenceY, undefined)
      Y._key = referenceY.getValue()
      return 1
    }
    if (X.marksLast()) {
      const referenceY = new IRISReference(Y._key, IRISReference.Type.STRING)
      irisnative._sortOrder(globalName, referenceY, undefined)
      Y._key = referenceY.getValue()
      return -1
    }
    if (Y.marksFirst()) {
      const referenceX = new IRISReference(X._key, IRISReference.Type.STRING)
      irisnative._sortOrder(globalName, referenceX, undefined)
      X._key = referenceX.getValue()
      return -1
    }
    if (Y.marksLast()) {
      const referenceX = new IRISReference(X._key, IRISReference.Type.STRING)
      irisnative._sortOrder(globalName, referenceX, undefined)
      X._key = referenceX.getValue()
      return 1
    }
    const referenceX = new IRISReference(X._key, IRISReference.Type.STRING)
    const referenceY = new IRISReference(Y._key, IRISReference.Type.STRING)
    const sortOrder = irisnative._sortOrder(globalName, referenceX, referenceY)
    X._key = referenceX.getValue()
    Y._key = referenceY.getValue()
    return sortOrder
  }
  
  /**
   * Returns the sorted order of two subscripts.
   * @param {Iris} irisnative the iris instance to use to communicate with the IRIS server
   * @param {string} globalName the name of the global node whose subscripts we want to sort
   * @param {*} keyX subscript to sort
   * @param {*} keyY subscript to sort
   * @returns 0 if equal, -1 if keyX if first and 1 if keyY is first
   */
  static _sortOrderByKey (irisnative, globalName, keyX, keyY) {
    return this._sortOrder(irisnative, globalName, new _point(keyX), new _point(keyY))
  }

  /**
   * Makes a copy of the current _point for the iterator
   * @returns a new _point
   */
  _iteratorCopy () {
    return new _point(this._key, this._inclusive)  
  }

}

module.exports._point = _point
